package com.quincaisoft.expenses.application;
import com.quincaisoft.expenses.api.ExpenseService;import com.quincaisoft.expenses.infrastructure.ExpenseEntity;import com.quincaisoft.tenders.api.TenderService;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.function.Supplier;
@Service public class DefaultExpenseService implements ExpenseService {
 private final EntityManager em;private final ScopedTransactions tx;private final TenderService tenders;private final FinanceService finance;private final JsonMapper json;
 public DefaultExpenseService(EntityManager em,ScopedTransactions tx,TenderService tenders,FinanceService finance,JsonMapper json){this.em=em;this.tx=tx;this.tenders=tenders;this.finance=finance;this.json=json;}
 private Expense view(ExpenseEntity r){return new Expense(r.id,r.businessDate,r.category,r.payee,""+r.amountXaf,r.status,r.version,r.paidFactId);}
 private ExpenseEntity get(UUID id){var s=TenantContext.current();var r=em.find(ExpenseEntity.class,new ExpenseEntity.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Scoped expense not found");return r;}
 private void reason(String value){if(value==null||value.trim().length()<3||value.length()>2000)throw new IllegalArgumentException("Reason required");}
 private Expense once(UUID op,String material,Supplier<ExpenseEntity> action){if(op==null)throw new IllegalArgumentException("Operation required");return tx.execute(()->{var s=TenantContext.current();String hash=hash(material);em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",s.tenantId()+":"+op).getSingleResult();var rows=em.createNativeQuery("select request_hash,company_id,branch_id,response_json::text,source_id from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",op).getResultList();if(!rows.isEmpty()){Object[] row=(Object[])rows.getFirst();if(!hash.equals(row[0])||!s.companyId().equals(row[1])||!s.branchId().equals(row[2]))throw new IllegalStateException("Operation conflict");get((UUID)row[4]);if(row[3]==null)throw new IllegalStateException("Committed operation response expired");return json.readValue((String)row[3],Expense.class);}var r=action.get();em.flush();var result=view(r);em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json) values(:t,:o,:c,:b,:h,'EXPENSE',:i,cast(:r as jsonb))").setParameter("t",s.tenantId()).setParameter("o",op).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("i",r.id).setParameter("r",json.writeValueAsString(result)).executeUpdate();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:i,:c,:b,:o,'ExpenseChanged.v1','expense',:a,cast(:p as jsonb))").setParameter("t",s.tenantId()).setParameter("i",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",op).setParameter("a",r.id).setParameter("p",json.writeValueAsString(result)).executeUpdate();return result;});}
 public List<Expense> list(){return tx.execute(()->em.createQuery("select r from ExpenseEntity r order by r.businessDate desc,r.id",ExpenseEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Expense draft(Draft p){reason(p.reason());if(p.businessDate()==null||p.category()==null||p.category().isBlank()||p.category().length()>100||p.payee()==null||p.payee().isBlank()||p.payee().length()>200||p.amountXaf()==null||!p.amountXaf().matches("[1-9][0-9]*"))throw new IllegalArgumentException("Expense date, category, payee and positive exact XAF required");long amount=Long.parseLong(p.amountXaf());return once(p.operationId(),"DRAFT|"+p,()->{finance.requireOpenPeriod(p.businessDate());var s=TenantContext.current();var r=new ExpenseEntity();r.id=UUID.randomUUID();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.createdBy=s.actorId();r.businessDate=p.businessDate();r.category=p.category();r.payee=p.payee();r.amountXaf=amount;r.reason=p.reason();r.status="DRAFT";em.persist(r);return r;});}
 public Expense command(UUID id,String action,Command p){reason(p.reason());return once(p.operationId(),action+"|"+id+"|"+p,()->{var r=get(id);finance.requireOpenPeriod(r.businessDate);if(r.version!=p.version())throw new RevisionConflict("Expense changed");var actor=TenantContext.current().actorId();switch(action){case "submit"->{if(!Set.of("DRAFT","REJECTED").contains(r.status))throw new IllegalStateException("Draft expense required");r.status="IN_REVIEW";r.submittedBy=actor;r.approvedBy=null;}case "approve","reject"->{if(!r.status.equals("IN_REVIEW"))throw new IllegalStateException("Expense awaiting review required");if(actor.equals(r.submittedBy))throw new IllegalArgumentException("Independent reviewer required");r.status=action.equals("approve")?"APPROVED":"REJECTED";r.approvedBy=action.equals("approve")?actor:null;}case "pay"->{if(!r.status.equals("APPROVED")||r.approvedBy==null)throw new IllegalStateException("Independently approved expense required");var child=UUID.nameUUIDFromBytes(("expense-payment:"+p.operationId()).getBytes(StandardCharsets.UTF_8));var fact=tenders.expense(new TenderService.CashExpense(child,r.id,p.cashSessionId(),r.businessDate,""+r.amountXaf,p.reason()));r.paidFactId=fact.id();r.status="POSTED";}case "cancel"->{if(!Set.of("DRAFT","REJECTED","IN_REVIEW").contains(r.status))throw new IllegalStateException("Only unapproved expense can cancel");r.status="CANCELLED";}default->throw new IllegalArgumentException("Unsupported expense command");}r.reason=p.reason();return r;});}
 private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
